{"tex_content": "\documentclass[sloppy,11pt]{article}
\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{amsmath}
\usepackage{url}
\usepackage{caption}
\usepackage{subcaption}

\title{Transcriptional Metabolic States in Meningioma Brain Single-Cell RNA-seq Data}
\author{}
\date{}

\begin{document}

\maketitle

\section*{Abstract}
This study investigates whether transcriptional metabolic states can be identified as distinct clusters in single-cell RNA-seq data from meningioma brain tissue. We analyze 58,843 cells using 1,984 Reactome metabolic genes.

\section{Methods}
\subsection{Data Processing}
Raw UMI counts were normalized using log1p transformation:
\begin{equation}
\log1p = \log(1+x)
\end{equation}
where $x$ represents the normalized expression value.

\subsection{Clustering Analysis}
Leiden clustering was performed with multiple seeds and resolutions. Confounders assessed: patient, sample, cell type, complexity, and cell cycle.

\section{Results}
\subsection{Global Clustering Results}
\begin{table}[h]
\centering
\toprule
Metric & Value \\
\midrule
Number of clusters & 15 \\
Silhouette score & 0.10 \\
Mean pairwise ARI & 0.80 \\
Random controls exceeding or equal & 0 \\
Random controls total & 19 \\
Add-one rank fraction & 0.05 \\
\bottomrule
\end{table}

\subsection{Cell-Type Association}
Confounding factors were assessed for their impact on cluster assignment.

\subsection{Within-Replicate Sensitivity}
Replicate sensitivity analysis was performed across multiple seeds and resolutions.

\section{Discussion}
The analysis reveals whether metabolic gene expression patterns can computationally separate cells into distinct groups. However, the inconclusive conclusion regarding discrete biological metabolic states requires careful interpretation.

\section{Conclusion}
Metabolic genes can form computational clusters, but this does not prove discrete biological metabolic states.

\end{document}
