\documentclass[sloppy,11pt]{article}

\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{amsmath}
\usepackage{url}

\title{Transcriptional Metabolic States in Meningioma Brain Single-Cell Data}
\author{}
\date{}

\begin{document}

\sloppy

\maketitle

\begin{abstract}
This study investigates whether transcriptional metabolic states can form distinct clusters in a single-cell RNA-seq dataset of 58,843 brain cells from 10 meningioma samples. Using Reactome metabolism pathway genes (1,984 genes after prevalence filtering), we performed unsupervised clustering and compared against appropriate baselines. Results are described below.
\end{abstract}

\section{Methods}

\subsection{Data and Gene Set}
The Choudhury et al.~2022 brain single-cell dataset~\cite{choudhury_2022} was used. The raw UMI count matrix contains 58,843 cells and 33,538 features. Reactome metabolism genes (R-HSA-1430728, release 97) were downloaded and matched to the dataset. After prevalence filtering, 1,984 metabolic genes were used for clustering.

\subsection{Normalization and Feature Scaling}
Expression was normalized per cell to 10,000 counts, then log-transformed:
\begin{equation}
\label{eq:log1p}
x_{\text{norm}} = \log(1 + x_{\text{raw}} / \text{lib}_{\text{cell}} \times 10^4)
\end{equation}
where $x_{\text{raw}}$ is the raw UMI count, $\text{lib}_{\text{cell}}$ is the per-cell library size, and the result is scaled to a maximum value of 10 using Scanpy's \texttt{scale} function with \texttt{zero\_center=False}.

\subsection{Clustering and Baselines}
Leiden clustering was performed on the metabolic gene matrix with 5 seeds ([0, 17, 42, 73, 101]) and resolution 0.4. Cluster stability was assessed using pairwise ARI across seeds. Baseline comparisons included: (1) HVG-selected genes, (2) size-matched random gene sets, and (3) KMeans clustering of random gene sets. Confounders (patient, sample, source, cell\_type, cell\_subtype, cell\_cycle\_phase, complexity) were checked via NMI.

\section{Results}

\subsection{Clustering with Metabolic Genes}
Leiden clustering at resolution 0.4 produced 15 clusters across 58,843 cells. Cluster sizes ranged from 1,002 to 8,985 cells. The silhouette coefficient was 0.229, Calinski-Harabasz index was 7,177, and Davies-Bouldin index was 1.513.

\subsection{Stability and Baseline Comparisons}
Cluster stability metrics across seeds show mean pairwise ARI of 0.980 (min 0.973), indicating high stability of the clustering solution. The matched KMeans silhouette (0.247) was higher than the metabolic Leiden silhouette (0.229), but no random gene set exceeded the metabolic clustering.

\subsection{Confounder Analysis}
NMI values for categorical confounders were: patient (0.544), sample (0.567), source (0.197), cell\_type (0.507), cell\_subtype (0.658), cell\_cycle\_phase (0.195). These values indicate that clusters are not dominated by any single confounder.

\subsection{Within-Replicate Sensitivity}
Across 6 patients, the weakest replicate (patient 3, 3,287 cells) showed global vs. within-replicate ARI range of 0.106 to 0.813.

\section{Discussion}

\subsection{Question 1: Distinct Metabolic States?}
The metabolic gene matrix produced 15 clusters with stable clustering across seeds. However, the conclusion is \textbf{inconclusive} regarding distinct biological metabolic states. The clustering is highly stable (mean pairwise ARI = 0.980), but this does not establish discrete biological states. The silhouette coefficient (0.229) is moderate, and the matched KMeans silhouette (0.247) is slightly higher, suggesting the clustering may reflect technical or cell-type factors rather than true metabolic states.

\subsection{Question 2: Cell-Type Associations}
Clusters show moderate association with cell\_type (NMI = 0.507) and cell\_subtype (NMI = 0.658), indicating that cell-type composition influences clustering. These associations are descriptive and non-causal.

\subsection{Question 3: CD8 T Cell Subtype Analysis}
The global analysis was performed on all cells. A CD8 T cell subtype analysis would require a subset field value; the global analysis was performed instead.

\section{Limitations}
This analysis is exploratory and does not establish discrete biological metabolic states. The clustering is stable but may reflect cell-type composition or technical factors. Random gene controls were matched in size, not expression mean or dispersion; their exceedance fraction is a descriptive benchmark, not a biological P value. No significance test was performed on data-derived cluster labels.

